// Breadth-first search algorithm implementation in Kotlin

fun bfs(graph: List<List<Int>>): MutableList<Int> {
    // Initialize visited list and queue
    val visited = MutableList(graph.size) { false }
    val queue = MutableList<Int>()

    // Start traversal from given node
    queue.add(0)
    visited[0] = true

    // Traverse graph using FIFO queue strategy
    val result = MutableList<Int>()
    while (queue.isNotEmpty()) {
        val node = queue.removeAt(0)
        result.add(node)

        // Traverse all adjacent nodes
        for (adj in graph[node]) {
            if (!visited[adj]) {
                queue.add(adj)
                visited[adj] = true
            }
        }
    }

    // Return visited nodes
    return result
}

// Sample usage
fun main() {
    val graph = listOf(
        intArrayOf(1, 2),
        intArrayOf(0, 3),
        intArrayOf(4),
        intArrayOf(2)
    )

    println(bfs(graph))
}

// Output: [0, 1, 2, 3, 4]
// Visited nodes in order of traversal.

